async function reinstall(job: Job) {
  const server = await loadServer(job);
  if (SANDBOX) {
    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
    await notify(
      server.userId,
      `Server ${server.hostname} reinstalled (sandbox)`,
      "The sandbox server was reinstalled (no real VM was touched).",
      `/dashboard/servers/${server.id}`
    );
    return;
  }
  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
  // EVERY disk the vmid owns, including attached block-storage Volume disks
  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
  // by that vmid, and both purge and the default destroy (which removes disks
  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
  // can be re-attached after the reinstall. This runs BEFORE any status change or
  // destructive call, so a blocked reinstall touches nothing.
  //
  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
  // let the worst path through: fill a volume, Detach (the UI says "Data is
  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
  // Detaching is therefore NOT sufficient protection, and telling the customer to
  // detach was wrong advice; they must delete the volume (which destroys just
  // that disk, deliberately) or move it to another server first.
  const pinnedVolumes = await db.volume.findMany({
    where: { serverId: server.id },
  });
  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
  const realPinned = pinnedVolumes.filter(
    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
  );
  if (realPinned.length > 0) {
    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
    throw new Error(
      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
        `Reinstalling purges every disk this server owns — including detached volumes ` +
        `that are still assigned to it — and that cannot be undone.`
    );
  }

  const { conn } = await nodeFor(server);
  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
  if (server.vmid) await destroyVm(conn, server.vmid);
  await provision(job);
}

